const response = $input.first().json;
let analysis;

try {
  // Claude retorna en response.content[0].text
  const claudeText = response.content?.[0]?.text || JSON.stringify(response);

  // Extraer JSON del response
  const jsonMatch = claudeText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (error) {
  console.error('Parse error:', error);
  // Fallback si Claude no retorna JSON válido
  analysis = {
    language: 'es',
    intent: 'other',
    sentiment: 'neutral',
    bookingData: {
      date: null,
      persons: null,
      tourType: null
    },
    keyTopics: []
  };
}

return {
  json: {
    ...analysis,
    originalMessage: $('Extraer Datos del Mensaje').item.json.messageText,
    customerPhone: $('Extraer Datos del Mensaje').item.json.customerPhone,
    customerName: $('Extraer Datos del Mensaje').item.json.customerName
  }
};

const prevData = $input.first().json;
const bookingResponse = prevData;

const language = $('Parsear Análisis de Claude').item.json.language || 'es';
const bookingId = bookingResponse.bookingId;

const messages = {
  es: `✅ ¡Reserva confirmada! Tu código de reserva es: ${bookingId}. Recibirás un email de confirmación pronto.`,
  en: `✅ Booking confirmed! Your booking code is: ${bookingId}. You will receive a confirmation email soon.`,
  pt: `✅ Reserva confirmada! Seu código de reserva é: ${bookingId}. Você receberá um email de confirmação em breve.`
};

return {
  json: {
    ...prevData,
    confirmationMessage: messages[language] || messages.es,
    bookingCreated: true,
    customerPhone: $('Parsear Análisis de Claude').item.json.customerPhone
  }
};

const responseData = $input.first().json;
const claudeResponse = responseData.content?.[0]?.text || responseData.text || 'Respuesta no disponible';

return {
  json: {
    responseText: claudeResponse,
    customerPhone: $('Parsear Análisis de Claude').item.json.customerPhone
  }
};
